Deno.test("observability model: response schemas tolerate unexpected data", () => {
  // config: empty entity (every field absent) still validates.
  assertEquals(resourceSchema("config").safeParse({}).success, true);
  // config: unknown keys are preserved, not stripped or rejected.
  {
    const parsed = resourceSchema("config").safeParse({ unexpected_field: 1 });
    assertEquals(parsed.success, true);
    // A plain z.object would also succeed, but would strip the key.
    assertEquals(
      JSON.stringify(parsed.data).includes("unexpected_field"),
      true,
    );
  }
  // structures_dashboard: empty entity (every field absent) still validates.
  assertEquals(
    resourceSchema("structures_dashboard").safeParse({}).success,
    true,
  );
  // structures_dashboard: unknown keys are preserved, not stripped or rejected.
  {
    const parsed = resourceSchema("structures_dashboard").safeParse({
      unexpected_field: 1,
    });
    assertEquals(parsed.success, true);
    // A plain z.object would also succeed, but would strip the key.
    assertEquals(
      JSON.stringify(parsed.data).includes("unexpected_field"),
      true,
    );
  }
  // deployment: empty entity (every field absent) still validates.
  assertEquals(resourceSchema("deployment").safeParse({}).success, true);
  // deployment: unknown keys are preserved, not stripped or rejected.
  {
    const parsed = resourceSchema("deployment").safeParse({
      unexpected_field: 1,
    });
    assertEquals(parsed.success, true);
    // A plain z.object would also succeed, but would strip the key.
    assertEquals(
      JSON.stringify(parsed.data).includes("unexpected_field"),
      true,
    );
  }
  // event: empty entity (every field absent) still validates.
  assertEquals(resourceSchema("event").safeParse({}).success, true);
  // event: unknown keys are preserved, not stripped or rejected.
  {
    const parsed = resourceSchema("event").safeParse({ unexpected_field: 1 });
    assertEquals(parsed.success, true);
    // A plain z.object would also succeed, but would strip the key.
    assertEquals(
      JSON.stringify(parsed.data).includes("unexpected_field"),
      true,
    );
  }
});

Deno.test({
  name: "observability model: HTTP errors name the request and status",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi({
      "GET /api/config": { status: 500, json: { message: "boom" } },
    }, async ({ run }) => {
      const err = await assertRejects(() => run("get_config", {}), Error);
      assertStringIncludes(err.message, "GET /api/config");
      assertStringIncludes(err.message, "500");
      assertStringIncludes(err.message, "boom");
    });
  },
});

